function stopQr(){qrStream.current?.getTracks().forEach(t=>t.stop());qrStream.current=null;setQrBusy(false)}
function closeQr(){stopQr();setQrOpen(false);setQrProduct(null);setQrMessage("")}
function matchQr(raw:string){const v=decodeURIComponent(raw).toLowerCase();return products.find(p=>v.includes(p.name.toLowerCase())||v.includes(p.name.toLowerCase().replace(/[^a-z0-9]+/g,"-")))}
async function startQr(){setQrMessage("");try{setQrBusy(true);const stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:"environment"}}});qrStream.current=stream;if(!qrVideo.current)throw new Error("video unavailable");qrVideo.current.srcObject=stream;qrVideo.current.setAttribute("playsinline","true");await qrVideo.current.play();const found=(raw:string)=>{const p=matchQr(raw);stopQr();if(p){setQrProduct(p);setQrMessage("")}else setQrMessage(qr.notFound)};if("BarcodeDetector" in window){const Detector=(window as any).BarcodeDetector;const detector=new Detector({formats:["qr_code"]});const scan=async()=>{if(!qrStream.current||!qrVideo.current)return;try{const codes=await detector.detect(qrVideo.current);if(codes?.[0]?.rawValue){found(String(codes[0].rawValue));return}}catch{}requestAnimationFrame(scan)};requestAnimationFrame(scan);return}const {BrowserQRCodeReader}=await import("@zxing/browser");const reader=new BrowserQRCodeReader();reader.decodeFromVideoElement(qrVideo.current,(result)=>{if(result&&qrStream.current)found(result.getText())})}catch{stopQr();setQrMessage(qr.camera)}}
async function askRala(e:FormEvent){e.preventDefault();const q=aiInput.trim();if(!q||aiBusy)return;const next=[...aiMessages,{role:"user" as const,content:q}];setAiMessages(next);setAiInput("");setAiBusy(true);try{const {data:{session}}=await supabase.auth.getSession();const r=await fetch("/api/rala-ai",{method:"POST",headers:{"Content-Type":"application/json",Authorization:"Bearer "+(session?.access_token||"")},body:JSON.stringify({lang,messages:next})});const j=await r.json();setAiMessages(m=>[...m,{role:"assistant",content:r.ok?j.answer:(j.error||"RALA AI kunne ikke svare akkurat nå.")}])}catch{setAiMessages(m=>[...m,{role:"assistant",content:"RALA AI kunne ikke svare akkurat nå."}])}finally{setAiBusy(false)}}async function changeLanguage(v:Lang){setLang(v);await supabase.rpc("set_my_language",{p_language:v});setProfile((p:any)=>({...p,language:v}))}
async function saveMyPhone(e:FormEvent){e.preventDefault();setUserMessage("");const {error}=await supabase.rpc("set_my_phone",{p_phone:myPhone});if(error){setUserMessage("Kunne ikke lagre telefonnummer.");return}setProfile((p:any)=>({...p,phone:myPhone.trim()||null}));setUserMessage("✓ Telefonnummer er lagret.")}
async function setProjectLeader(projectId:string,leaderId:string){setUserMessage("");const {error}=await supabase.rpc("set_project_responsible_leader",{p_project_id:projectId,p_leader_id:leaderId||null});if(error){setUserMessage("Kunne ikke endre ansvarlig leder: "+error.message);return}setProjects((xs:any[])=>xs.map((p:any)=>p.id===projectId?{...p,responsible_leader_id:leaderId||null}:p));setUserMessage("✓ Ansvarlig leder er lagret.")}
